import os,json,sys,numpy as np
from rcb_client import Robot
from PIL import Image
r=Robot()
CAMS=['egoview','robot0_agentview_right','robot0_eye_in_right_hand']
T=np.array([2.66969,-2.13364,0.89794])
def world_to_base(p):
 x,y,z=p;return np.array([y-T[1],-(x-T[0]),z-T[2]])
def current():
 o=r.get_obs(cameras=CAMS,include_depth=True,video='none')
 d=dict(zip(o.meta['proprio']['layout'],o.meta['proprio']['now']))
 return o,np.array([d['cmd_'+x] for x in r.spec()['action_types']['ee_pose']['layout']],float)
def save(o,tag):
 o.save('/app/runs/'+tag)
 print(tag,'steps',o.meta['control_steps'],'time_left',o.meta['time_left_s'],flush=True)
def move(tag,right=None,left=None,rhand=None,lhand=None,steps=30):
 o,a=current(); b=a.copy()
 if right is not None:b[:3]=world_to_base(right)
 if left is not None:b[6:9]=world_to_base(left)
 if rhand is not None:b[12:18]=rhand
 if lhand is not None:b[18:24]=lhand
 A=np.linspace(a,b,steps)
 o=r.submit('ee_pose',A,cameras=CAMS,include_depth=True,video='none',note=tag)
 save(o,tag)
 return o
if __name__=='__main__':
 tag=sys.argv[1]
 if tag=='approach':move('approach',right=(3.03,-1.91,1.055),steps=40)
 elif tag=='lower':move('lower',right=(3.03,-1.91,0.98),steps=35)
 elif tag=='close':move('close',rhand=[1.2,1.2,1.2,1.2,1.2,1.2],steps=35)
 elif tag=='lift':move('lift',right=(3.03,-1.91,1.17),steps=45)
